with parsed as (select id, latency_ms, status_code, payload_json, context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, array_contains(map_keys(context), 'region') as has_region, context['region'] as region from app_logs) select case when duration_sec >= 4.3 then 'LARGE' else 'SMALL' end as duration_sec_tier, case when latency_ms >= 1982 then 'LARGE' else 'SMALL' end as latency_ms_tier, round(avg(status_code), 2) as avg_status_code, bit_and(latency_ms) as latency_ms_bit_and, min(status_code) as min_status_code, rank() over (partition by case when duration_sec >= 4.3 then 'LARGE' else 'SMALL' end order by round(avg(status_code), 2) desc) as avg_status_code_rank from parsed group by case when duration_sec >= 4.3 then 'LARGE' else 'SMALL' end, case when latency_ms >= 1982 then 'LARGE' else 'SMALL' end having round(avg(status_code), 2) >= 0;
